TIERS = {"hot": {"ms": 5, "c": 10}, "cold": {"ms": 500, "c": 1}}
def route(urgent):
    if urgent: return "hot"
    return min(TIERS, key=lambda t: TIERS[t]["c"])
print("urgent ->", route(True), "| batch ->", route(False))

